    /// <summary>
    /// COCO method
    /// </summary>
    /// <param name = "_salesParmLine">table buffer</param>
    /// <returns>boolean</returns>
    protected boolean checkDiscardLine(Common _salesParmLine)
    {
        boolean             ok = next checkDiscardLine(_salesParmLine);
        SalesParmLine       salesParmLine = _salesParmLine as SalesParmLine;
        METCustParameters   METCustParameters = METCustParameters::Find();

        if(METCustParameters.IncludeCancelledLines || METCustParameters.IncludeLineWithZeroQty)
        {
            ok = false;
        }
        salesLine = salesParmLine.salesLine();

        return ok;        
    }

    /// <summary>
    /// COC method
    /// </summary>
    /// <param name = "_salesParmLine">table buffer</param>
    protected void createJournalLine(Common _salesParmLine)
    {
        METsalesLine                            metsalesLine;
        METIndicators                           indicatorValue;
        ReqItemTable                            ReqItemTableLoc;
        METReqItemTable                         METReqItemTable;
        InventDim                               metInventDimReq;
        RetailSalesQuotationDiscountLineView    RetailSalesQuotationDiscountLineView;
        RetailPeriodicDiscount                  RetailPeriodicDiscount;
        GUPPriceComponentCode                   GUPPriceComponentCode;

        next createJournalLine(_salesParmLine);

        metsalesLine = salesLine.metsalesLine();
        if(metsalesLine && !salesLine.salestable().lastConfirmDate())
        {
            metsalesLine.selectForUpdate(true);

            metsalesLine.SalesUnitWeight = METWHSPhysDimUOMSite::convertWeight(
                                salesLine.ItemId, 1, salesLine.SalesUnit, salesLine.inventDim(), true);
            metsalesLine.SalesUnitVolume = METWHSPhysDimUOMSite::convertVolume(
                                salesLine.ItemId, 1,  salesLine.SalesUnit, salesLine.inventDim());
            metsalesLine.SalesUnitCase = roundUp(UnitOfMeasureConversion::findByConversion(
                                UnitOfMeasure::findBySymbol(salesLine.SalesUnit).RecId,
                                UnitOfMeasure::findBySymbol(METConstants::unitcase).RecId,
                                EcoResProduct::findByProductNumber(salesLine.ItemId).RecId).Factor, 0);

            metInventDimReq.InventSiteId        = salesLine.inventDim().InventSiteId;
            metInventDimReq.InventLocationId    = salesLine.inventDim().InventLocationId;

            metInventDimReq = InventDim::findOrCreate(metInventDimReq);

            select firstonly RecId from ReqItemTableLoc
                where ReqItemTableLoc.ItemId == salesLine.ItemId &&
                ReqItemTableLoc.CovInventDimId == metInventDimReq.InventDimId
                exists join METReqItemTable
                where METReqItemTable.RefRecId == ReqItemTableLoc.RecId &&
                METReqItemTable.SlotLoc1Area == METConstants::SEC;
            if(ReqItemTableLoc.recId)
            {
                if(metsalesLine.Indicators)
                {
                    if(!strFind(metsalesLine.Indicators, METConstants::IndicatorR, 1, strLen(metsalesLine.Indicators)))
                    {
                        metSalesLine.Indicators = METConstants::IndicatorR+ METConstants::Comma + metSalesLine.Indicators;
                    }
                }
                else
                {
                    metsalesLine.Indicators = METConstants::IndicatorR;
                }                    
            }

            select firstonly PriceComponentCodeGroup from GUPPriceComponentCode 
                where GUPPriceComponentCode.PriceComponentCodeGroup
                exists join RetailPeriodicDiscount
                where RetailPeriodicDiscount.PriceComponentCodeName == GUPPriceComponentCode.Name
                exists join RetailSalesQuotationDiscountLineView
                where RetailSalesQuotationDiscountLineView.InventTransId == salesLine.InventTransId &&
                RetailSalesQuotationDiscountLineView.PeriodicDiscountOfferId == RetailPeriodicDiscount.OfferId;
            if(GUPPriceComponentCode.PriceComponentCodeGroup)
            {
                indicatorValue  = GUPPriceComponentCode.PriceComponentCodeGroup == METConstants::promotion? METConstants::promotionInd:
                    GUPPriceComponentCode.PriceComponentCodeGroup == METConstants::override? METConstants::overrideInd:
                    GUPPriceComponentCode.PriceComponentCodeGroup == METConstants::Bonus? METConstants::BonusInd : METConstants::emptyString;

                if(metsalesLine.Indicators)
                {
                    if(!strFind(metsalesLine.Indicators, METConstants::POB, 1, strLen(metsalesLine.Indicators)))
                    {
                        metsalesLine.Indicators = indicatorValue + METConstants::Comma + metsalesLine.Indicators;
                    }
                }
                else
                {
                    metsalesLine.Indicators = indicatorValue;
                }
            }
            metsalesLine.update();
        }
    }
